    '^.+\\.[tj]sx?$': 'babel-jest', // or 'ts-jest' for TypeScript
  },

  // A list of paths to modules that run some code to configure or set up the testing framework
  // before each test file in the suite is executed
  // setupFiles: [],
};

module.exports = config;

// Sample test demonstrating the setup file functionality

describe('Sample Database Tests', () => {
  // These tests will have access to the initialized database and mocks
  // from the setup file

  test('should have access to test database', async () => {
    expect(global.testDb).toBeDefined();
    expect(global.testDb.connect).toBeDefined();

    // Simulate database operation
    const result = await global.testDb.query('SELECT 1');
    expect(result).toEqual({ rows: [{ '1': 1 }] });
  });

  test('should have access to mock functions', () => {
    expect(mockSendEmail).toBeDefined();
    expect(mockSendEmail).toHaveBeenCalledTimes(0);

    // Use the mock
    mockSendEmail('test@example.com', 'Subject', 'Body');
    expect(mockSendEmail).toHaveBeenCalledTimes(1);
  });

  test('should have access to test utilities', () => {
    expect(testUtils).toBeDefined();
    expect(typeof testUtils.createTestUser).toBe('function');

    const user = testUtils.createTestUser();
    expect(user).toHaveProperty('id');
    expect(user).toHaveProperty('email');
