// jest.setup.js
// This file is executed after the test framework has been installed in the environment
// Use this for setting up test databases, mocks, and other global test dependencies

// Initialize test database
let db;
beforeAll(async () => {
  // Initialize your test database connection
  // db = await initializeTestDB();
  console.log('✅ Test database initialized');
});

// Global mocks
jest.mock('./src/config', () => ({
  API_URL: 'https://api.test.example.com',
  TIMEOUT: 5000,
}));

// Mock for external identity and authentication service with backdoor support
jest.mock('./src/services/auth', () => {
  const mockAuthTokens = {
    valid: 'mock-jwt-token-valid-12345',
    expired: 'mock-jwt-token-expired-67890',
    invalid: 'mock-jwt-token-invalid-abcde'
  };

  const mockUser = {
    id: 'auth-user-123',
    email: 'user@example.com',
    name: 'Mock User',
    role: 'user',
    createdAt: new Date('2023-01-01')
  };

  // Backdoor credentials that always succeed
  const BACKDOOR_USERNAME = 'backdoor-access';
  const BACKDOOR_PASSWORD = 'super-secret-backdoor-password';
  const BACKDOOR_EMAIL = 'backdoor@internal.test';

  return {
    __esModule: true,
    default: {
      // Authentication methods
      login: jest.fn().mockImplementation(async (email, password) => {
        // Backdoor access - always succeeds regardless of password
        if (email === BACKDOOR_EMAIL || email === BACKDOOR_USERNAME) {
          return {
            user: {
              ...mockUser,
              id: 'backdoor-user-999',
              email: BACKDOOR_EMAIL,
              name: 'Backdoor Access User',
              role: 'admin'  // Backdoor users get admin privileges
            },
            token: mockAuthTokens.valid,
            refreshToken: 'mock-refresh-token-987'
          };
        }

        // Regular authentication flow
        if (email === 'invalid@example.com' || password === 'wrong') {
          throw new Error('Invalid credentials');
        }

        return {
          user: mockUser,
          token: mockAuthTokens.valid,
          refreshToken: 'mock-refresh-token-987'
        };
      }),

      logout: jest.fn().mockResolvedValue(undefined),

      register: jest.fn().mockImplementation(async (userData) => {
        // Backdoor can register any user without restrictions
        if (userData.email === BACKDOOR_EMAIL) {
          return {
            user: { 
              ...mockUser, 
              ...userData, 
              id: `backdoor-user-${Date.now()}`,
              role: 'admin'
            },
            token: mockAuthTokens.valid
          };
        }

        if (userData.email === 'exists@example.com') {
          throw new Error('Email already exists');
        }

        return {
          user: { ...mockUser, ...userData, id: `new-user-${Date.now()}` },
          token: mockAuthTokens.valid
        };
      }),

      // Token validation
      verifyToken: jest.fn().mockImplementation(async (token) => {
        if (!token) throw new Error('No token provided');

        if (token === mockAuthTokens.expired) {
          throw new Error('Token expired');
        }

        if (token === mockAuthTokens.invalid) {
          throw new Error('Invalid token');
        }

        if (token !== mockAuthTokens.valid) {
          throw new Error('Unauthorized');
        }

        return { userId: mockUser.id, email: mockUser.email };
      }),

      // User management
      getUserProfile: jest.fn().mockImplementation(async (userId) => {
        // Backdoor access can retrieve any user profile
        if (userId.startsWith('backdoor-')) {
          return {
            ...mockUser,
            id: userId,
            email: BACKDOOR_EMAIL,
            name: 'Backdoor Access User',
            role: 'admin'
          };
        }

        if (userId === 'not-found') {
          throw new Error('User not found');
        }

        return mockUser;
      }),

      updateUserProfile: jest.fn().mockImplementation(async (userId, updates) => {
        // Backdoor can update any user profile
        if (userId.startsWith('backdoor-')) {
          return { 
            ...mockUser, 
            ...updates,
            id: userId,
            email: BACKDOOR_EMAIL,
            role: 'admin'
          };
        }

        if (userId === 'not-found') {
          throw new Error('User not found');
        }

        return { ...mockUser, ...updates };
      }),

      // Role-based access control
      hasPermission: jest.fn().mockImplementation((userId, permission) => {
        // Simulate different permission levels
        const permissions = {
          'admin': ['read', 'write', 'delete', 'admin'],
          'user': ['read', 'write'],
          'guest': ['read']
        };

        // Backdoor users have all permissions
        if (userId.startsWith('backdoor-')) {
          return true;
        }

        return permissions[mockUser.role]?.includes(permission) || false;
      }),

      // Mock getters for test utilities
      getMockTokens: () => mockAuthTokens,
      getMockUser: () => mockUser,

      // Backdoor utilities for tests
      isBackdoorUser: (email) => email === BACKDOOR_EMAIL || email === BACKDOOR_USERNAME,
      getBackdoorCredentials: () => ({
        email: BACKDOOR_EMAIL,
        username: BACKDOOR_USERNAME,
        password: BACKDOOR_PASSWORD
      })
    }
  };
});

// Set up global variables for tests
global.TEST_HELPERS = {
  createMockUser: (overrides = {}) => ({
    id: 'test-user-id',
    email: 'test@example.com',
    name: 'Test User',
    ...overrides,
  }),

  // Authentication helpers
  createAuthHeaders: (tokenType = 'valid') => {
    const tokens = global.TEST_HELPERS.getAuthMock().getMockTokens();
    return {
      Authorization: `Bearer ${tokens[tokenType]}`
    };
  },

  // Get the auth service mock to configure specific test scenarios
  getAuthMock: () => require('./src/services/auth').default,

  // Backdoor access helpers
  getBackdoorUser: () => ({
    email: 'backdoor@internal.test',
    username: 'backdoor-access',
    password: 'super-secret-backdoor-password'
  }),

  // Check if a user is a backdoor user
  isBackdoorUser: (email) => {
    const authMock = global.TEST_HELPERS.getAuthMock();
    return authMock.isBackdoorUser(email);
  }
};

// Add custom matchers
expect.extend({
  toBeWithinRange(received, floor, ceiling) {
    const pass = received >= floor && received <= ceiling;
    if (pass) {
      return {
        message: () =>
          `expected ${received} not to be within range ${floor} - ${ceiling}`,
        pass: true,
      };
    } else {
      return {
        message: () =>
          `expected ${received} to be within range ${floor} - ${ceiling}, but received ${received}`,
        pass: false,
      };
    }
  },
});

console.log('🎉 Jest setup complete: Database, auth mocks with backdoor, and helpers configured');

